mapper.select:
SELECT b.*, p.name AS pet_name, o.name AS owner_name FROM boarding_records b JOIN pets p ON b.pet_id = p.id JOIN owners o ON p.owner_id = o.id
b.status = #{status}
AND (LOWER(p.name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(o.name) LIKE LOWER(CONCAT('%', #{keyword}, '%')))
ORDER BY b.check_in_date DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(b.id) FROM boarding_records b JOIN pets p ON b.pet_id = p.id JOIN owners o ON p.owner_id = o.id
b.status = #{status}
AND (LOWER(p.name) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(o.name) LIKE LOWER(CONCAT('%', #{keyword}, '%')))
